{
  "title": "The Glass Diver's Escape",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party assembles at the ruined city gate.",
      "visual_description": "Crumbled stone archway with torn royal banners flapping in the wind. The glass diver adjusts his helmet while Mara studies a brass compass. The oracle lamp flickers beside them, casting long shadows across rubble-strewn ground.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of a cursed tower ahead.",
      "visual_description": "The lamp casts a warm glow on a tarnished metal signpost pointing toward a twisted spire. Its flame eye narrows as it speaks, and Mara notes the warning on her ink-stained sleeve.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The glass diver swims through a broken shop window to scout.",
      "visual_description": "A shattered storefront with glass shards hanging like teeth. The diver steps into the reflection and emerges inside a dusty shop, his coat reflecting fragmented city lights onto the floor.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "Mara consults her map at a collapsed fountain.",
      "visual_description": "A cracked stone fountain with stagnant water. Mara traces a route with her finger, compass swinging. The tin fox sniffs at the base, tail ticking.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The sleeping tax collector is found dozing on a pile of ledgers.",
      "visual_description": "Inside a half-collapsed archive, the collector snores with a ledger under his head. Stamped papers are stuck to his sleeves like makeshift armor. The oracle lamp hovers, its light glinting off a brass inkwell.",
      "characters": ["sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "The tin fox discovers a hidden passage behind a tapestry.",
      "visual_description": "A moth-eaten royal tapestry depicting a hunt, pushed aside by the fox's metal snout. A narrow stone corridor leads into darkness, dust motes swirling in the lamplight.",
      "characters": ["tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "Mara deciphers a clue from the tax collector's stamped papers.",
      "visual_description": "Mara holds a crumpled paper up to the lamp's glow. The collector shifts in his sleep, muttering. The ink reveals a floor plan of the palace's lower levels.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "The glass diver swims through a mirror to bypass a magic door.",
      "visual_description": "A tall, ornate mirror in a ruined hall. The diver presses his helmet against the glass, ripples spreading. On the other side, a corridor with no door at all.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "An armored patrol marches past their hiding spot.",
      "visual_description": "The party crouches behind a collapsed pillar. Heavy footsteps echo, and the glow of lanterns on armor plates reflects off the glass diver's helmet. The tin fox freezes, its blue eyes dimmed.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "The oracle lamp reveals a trap in the floor.",
      "visual_description": "A faint glyph on the stonework glows as the lamp's light passes over it. Mara steps back just in time. The floor tile sinks, and a spray of rusted bolts shoots upward.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "The sleeping tax collector is carried through a narrow corridor.",
      "visual_description": "Mara and the glass diver drag the snoring collector by his ledger straps through a tight passage. The tin fox leads, lamp floating behind. Stamped papers trail like a wake.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "They reach a grand hall with a sealed magic door.",
      "visual_description": "A massive door of inlaid crystal pulses with light. Old royal banners hang above, faded and torn. A stone pedestal with a keyhole sits before it. The oracle lamp's flame dims in the eerie glow.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "The glass diver retrieves a key from a reflecting pool.",
      "visual_description": "A shallow pool in the corner, its surface like black glass. The diver reaches into his own reflection, hand disappearing. He pulls out a brass key dripping with water.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Mara turns the key, and the door swings open.",
      "visual_description": "Mara inserts the key into the pedestal. The crystal door shimmers and splits, revealing a staircase upward. The tin fox's tail winds faster, its glass eyes bright.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The party ascends into a tower room with a view of the bridge.",
      "visual_description": "A circular room with broken windows overlooking a long stone bridge spanning a chasm. The oracle lamp's flame steadies as fresh air pours in. The collector snores on a dusty rug.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "Armored patrols converge on the tower base.",
      "visual_description": "From the window, the party sees lanterns bobbing below as armored figures surround the tower. Their voices echo up the stairwell. The tin fox's ears swivel.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The glass diver creates a mirror path across the bridge.",
      "visual_description": "The diver shatters a nearby mirror and steps into the shards, creating a shimmering pathway that arcs over the bridge. The party follows, running on reflected light above the stone.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "They escape across the bridge as the tower collapses behind them.",
      "visual_description": "The party reaches the far side. The mirror path shatters as the tower crumbles. Banners flutter down into the chasm. The oracle lamp's flame flickers once, then burns steady. The collector yawns, still asleep.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    }
  ],
  "gate_token": "keHk6y_tZj8bqOCJJSGfiw"
}

